command.stage2_normalizeAndCount_awk:
{
  line = $0
  gsub(/&&/, "\n", line)
  gsub(/\|\|/, "\n", line)
  gsub(/;/, "\n", line)
  gsub(/\|/, "\n", line)
  nseg = split(line, segs, "\n")
  for (s = 1; s <= nseg; s++) {
    seg = segs[s]
    gsub(/^[ \t]+/, "", seg)
    gsub(/[ \t]+$/, "", seg)
    if (seg == "") continue
    n = split(seg, a, " ")
    if (n == 0) continue
    t1 = a[1]
    if (t1 == "cd") continue
    if (t1 == "git" && n >= 2) { key = t1 " " a[2] }
    else if (t1 == "gh" && n >= 3) { key = t1 " " a[2] " " a[3] }
    else if (t1 == "gh" && n == 2) { key = t1 " " a[2] }
    else { key = t1 }
    count[key]++
  }
}
END { for (k in count) print count[k], k }
